/** Git review comment row view; timestamps are epoch milliseconds, outdated is computed on read. */
export type ReviewComment = types.gitUi.CommentAnchor & {
  /** UUID v7 generated by Bun.randomUUIDv7() when creating the comment. */
  id: string;
  /** Owning agent; its deletion permanently cascades to this row. */
  agent_id: string;
  /** Canonical repository host: local or an SSH alias, derived from the owned Canvas item. */
  host: string;
  /** Absolute repository directory derived from the owned Canvas item. */
  dir: string;
  /** Markdown comment body, 1–8192 UTF-8 bytes. */
  body: string;
  status: 'open' | 'resolved';
  /** Optional resolver note, at most 2048 UTF-8 bytes. */
  resolution_note: string | null;
  resolved_by: 'user' | 'agent' | null;
  sent_at: number | null;
  resolved_at: number | null;
  created_at: number;
  updated_at: number;
  /** False for immutable commit anchors; computed from current diff lines for worktree anchors. Never stored. */
  outdated: boolean;
};
